package com.argument.resulttrial;
import com.argument.common.exception.*;
import com.argument.finalreview.*;
import com.argument.exporttrial.*;
import com.argument.version.*;
import com.argument.version.port.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.argument.adjudication.AdjudicationService.require;
@Service @Profile("(local | test) & !prod") @Transactional(readOnly=true)
public class ResultTrialService {
 private final com.argument.finalreview.FrozenGraphValidation graphValidation;
 private final com.argument.adjudication.AdjudicationRepository sessions;private final VersionRepository versions;private final com.argument.segmentationtrial.SegmentationTrialRepository segmentation;private final FinalReviewRepository finals;private final AnnotationDependencies data;private final ExportBundleBuilder bundles;private final ExportTrialService exports;private final ExportTrialRepository files;private final ObjectMapper mapper;
 public ResultTrialService(com.argument.adjudication.AdjudicationRepository sessions,VersionRepository versions,com.argument.segmentationtrial.SegmentationTrialRepository segmentation,FinalReviewRepository finals,AnnotationDependencies data,ExportBundleBuilder bundles,ExportTrialService exports,ExportTrialRepository files,ObjectMapper mapper,com.argument.finalreview.FrozenGraphValidation graphValidation){this.graphValidation=graphValidation;this.sessions=sessions;this.versions=versions;this.segmentation=segmentation;this.finals=finals;this.data=data;this.bundles=bundles;this.exports=exports;this.files=files;this.mapper=mapper;}
 private void authorize(Actor actor){require(actor.permission("DOCUMENT_VIEW")&&(actor.role("ADMIN")||actor.role("TASK_CREATOR")),ErrorCode.FORBIDDEN,"仅管理员及任务创建者可读取授权成果");}
 public ObjectNode list(Actor actor,String guide,String source,int page,int size){authorize(actor);if(guide!=null)VersionJson.uuid(guide);require(source==null||Set.of("ORDINARY_JUDGMENT","GUIDING_CASE","REFERENCE_CASE").contains(source),ErrorCode.VALIDATION_ERROR,"无效来源类型");var rows=new ArrayList<ObjectNode>();for(var task:data.find("task",null,null)){if(!actor.role("ADMIN")&&!actor.id().equals(task.path("ownerUserId").asText()))continue;for(var doc:data.find("taskDocument","taskId",task.path("id").asText()))for(var v:finals.versions(doc.path("id").asText())){if(!"IN_DATABASE".equals(v.path("status").asText())||guide!=null&&!guide.equals(v.path("guideVersionId").asText()))continue;var document=data.read("document",doc.path("documentId").asText());if(source!=null&&!source.equals(document.path("sourceType").asText()))continue;var n=mapper.createObjectNode();n.set("version",v);n.set("document",document);n.set("guideVersion",data.read("guideVersion",v.path("guideVersionId").asText()));rows.add(n);}}rows.sort(Comparator.comparing(n->n.path("version").path("id").asText()));var result=mapper.createObjectNode().put("total",rows.size()).put("mode","LOCAL_TRIAL").put("teamReviewRequired",true);var items=result.putArray("items");rows.stream().skip((long)(page-1)*size).limit(size).forEach(items::add);return result;}
 public ObjectNode read(Actor actor,String id){authorize(actor);var snapshot=bundles.source(actor,id);var v=snapshot.path("version");var doc=data.read("taskDocument",v.path("taskDocumentId").asText());var result=mapper.createObjectNode().put("mode","LOCAL_TRIAL").put("teamReviewRequired",true);result.set("snapshot",snapshot);result.set("graphView",graphValidation.inspect(snapshot));result.set("document",data.read("document",doc.path("documentId").asText()));result.set("textVersion",data.read("text",v.path("documentTextVersionId").asText()));result.set("scope",data.read("scope",v.path("annotationScopeId").asText()));result.set("guideVersion",data.read("guideVersion",v.path("guideVersionId").asText()));result.set("labelDistribution",distribution(snapshot,"elements","labelDefinitionId","label",v.path("guideVersionId").asText()));result.set("relationDistribution",distribution(snapshot,"relations","relationDefinitionId","relationDefinition",v.path("guideVersionId").asText()));var sourceVersion=versions.snapshot(sessions.session(v.path("sessionId").asText(),false).path("sourceVersionIds").get(0).asText()).path("version");var cp=data.read("checkpoint",sourceVersion.path("segmentationCheckpointId").asText());var agreement=result.putObject("agreement");agreement.set("checkpointId",cp.path("id"));agreement.set("score",cp.path("agreementScore"));agreement.set("calculationId",cp.path("calculationId"));agreement.put("reproducible",cp.hasNonNull("calculationId"));if(cp.hasNonNull("calculationId")){var calculation=segmentation.get("CALCULATION",cp.path("calculationId").asText());agreement.set("calculation",calculation);}else agreement.put("notice","该历史关口为预置输入，不计为真实算法计算记录");return result;}
 private com.fasterxml.jackson.databind.node.ArrayNode distribution(ObjectNode snapshot,String field,String ref,String kind,String guide){var rows=mapper.createArrayNode();for(var definition:data.find(kind,"guideVersionId",guide)){long count=java.util.stream.StreamSupport.stream(snapshot.path(field).spliterator(),false).filter(n->n.path(ref).equals(definition.path("id"))).count();var row=rows.addObject();row.set("definitionId",definition.get("id"));row.set("code",definition.get("code"));row.set("name",definition.path("name"));row.put("count",count);}return rows;}
 public ObjectNode exportEvents(Actor actor,String id){exports.read(actor,id);var n=mapper.createObjectNode().put("mode","LOCAL_TRIAL").put("teamReviewRequired",true);var items=n.putArray("items");files.events().stream().filter(e->id.equals(e.path("exportId").asText())).sorted(Comparator.comparing(e->e.path("occurredAt").asText())).forEach(items::add);return n;}
 public ObjectNode reannotationSource(Actor actor,String id){authorize(actor);require(actor.role("TASK_CREATOR")&&actor.permission("TASK_CREATE"),ErrorCode.FORBIDDEN,"重标任务来源仅供有创建权限的任务创建者读取");var snapshot=bundles.source(actor,id);var doc=data.read("taskDocument",snapshot.path("version").path("taskDocumentId").asText());var n=mapper.createObjectNode().put("mode","LOCAL_TRIAL").put("teamReviewRequired",true).put("sourceTaskId",doc.path("taskId").asText()).put("sourceFinalVersionId",id).put("sourceContentDigest",FinalReviewService.contentDigest(snapshot));for(String f:List.of("documentTextVersionId","annotationScopeId","guideVersionId"))n.set(f,snapshot.path("version").path(f));return n;}
}
